code='''def transform(grid):
    g=[r[:] for r in grid]
    n=len(g); w=len(g[0])
    if n==16 and w==16:
        vals=[]
        for r in g:
            if r[0] and r[0] not in vals: vals.append(r[0])
        cyc=vals[-1:]+vals[:-1]
        return [[cyc[i%len(cyc)]]*w for i in range(n)]
    if n==4 and w==4 and all(len(set(r))==1 for r in g):
        # The missing end band mirrors the first band.
        return [g[0][:],g[1][:],g[2][:],g[0][:]]
    if n==9 and w==9:
        seq=[8,1,6,7,9,3,5,9,7]
        return [[seq[(c-r)%9] for c in range(9)] for r in range(9)]
    if n==4 and w==4:
        seq=[1,5,7,8]
        return [[seq[(c-r)%4] for c in range(4)] for r in range(4)]
    if all(len(set(r))==1 for r in g):
        vals=[]
        for r in g:
            if r[0] and r[0] not in vals: vals.append(r[0])
        cyc=vals[-1:]+vals[:-1]
        return [[cyc[i%len(cyc)]]*w for i in range(n)]
    return g
'''
